        pm.expect(resBody.job).to.eql(pm.iterationData.get("job"));
    } else if (pm.request.body && pm.request.body.raw) {
        // Trường hợp chạy trực tiếp không dùng file CSV
        const reqBody = JSON.parse(pm.request.body.raw);
        pm.expect(resBody.name).to.eql(reqBody.name);
        pm.expect(resBody.job).to.eql(reqBody.job);
    }
});

